mapper.select:
SELECT 
FROM smt_work_record r
LEFT JOIN smt_employee e ON e.id = r.employee_id AND e.del_flag = '0'
LEFT JOIN smt_work_type w ON w.id = r.work_type_id AND w.del_flag = '0'

    r.del_flag = '0'

        AND r.serial_no LIKE CONCAT('%', #{serialNo}, '%')


        AND r.employee_id = #{employeeId}


        AND r.work_type_id = #{workTypeId}


        AND r.status = #{status}


        AND r.location LIKE CONCAT('%', #{location}, '%')


        AND r.is_backfill = #{isBackfill}


        AND r.service_date = #{serviceDate}


        AND r.service_date >= #{params.beginServiceDate}


        AND r.service_date <= #{params.endServiceDate}


ORDER BY r.service_date DESC, r.start_time DESC, r.id DESC

SELECT 
FROM smt_work_record r
LEFT JOIN smt_employee e ON e.id = r.employee_id
LEFT JOIN smt_work_type w ON w.id = r.work_type_id
WHERE r.del_flag = '0'
  AND r.status = 'APPROVED'
  AND DATE_FORMAT(r.service_date, '%Y-%m') = #{month}

    AND r.employee_id = #{employeeId}


    AND r.work_type_id = #{workTypeId}

ORDER BY r.service_date DESC, r.start_time DESC

SELECT 
FROM smt_work_record r
LEFT JOIN smt_employee e ON e.id = r.employee_id AND e.del_flag = '0'
LEFT JOIN smt_work_type w ON w.id = r.work_type_id AND w.del_flag = '0'
WHERE r.del_flag = '0'
  AND r.employee_id = #{employeeId}

    AND DATE_FORMAT(r.service_date, '%Y-%m') = #{month}


    AND r.status = #{status}

ORDER BY r.service_date DESC, r.start_time DESC, r.id DESC
